s/class SwitchSorted\(SwitchGLU\):\n    """Stand-in for _FusedGateUpSwitchGLU\.sorted_experts: the stock expert outputs \[rows \* k, D\] in a shuffled order\n    with the inverse permutation that unsorts them\."""\n    def sorted_experts\(self, x, indices\):\n        y = SwitchGLU\.__call__\(self, x, indices\); y2 = y\.reshape\(-1, y\.shape\[-1\]\); n = y2\.shape\[0\]\n/class SwitchSorted(nn.Module):\n    """Stand-in for the routed experts (the real one is the fused, quantized switch layer; mlx_lm\x27s SwitchGLU is float32\n    only): E small gated MLPs, x [..., D] and indices [..., k] -> [..., k, D]; sorted_experts hands the same outputs over\n    as _FusedGateUpSwitchGLU.sorted_experts does, [rows * k, D] in a shuffled order with the inverse permutation."""\n    def __init__(self, dim, hid, n_exp):\n        nn.Module.__init__(self); s = 1.0 \/ np.sqrt(dim)\n        self.wg = mx.random.uniform(-s, s, (n_exp, hid, dim)); self.wu = mx.random.uniform(-s, s, (n_exp, hid, dim))\n        self.wd = mx.random.uniform(-1.0 \/ np.sqrt(hid), 1.0 \/ np.sqrt(hid), (n_exp, dim, hid))\n    def __call__(self, x, indices):\n        xe = x[..., None, :, None]                                  # [..., 1, D, 1]\n        hg = (self.wg[indices] @ xe)[..., 0]; hu = (self.wu[indices] @ xe)[..., 0]   # [..., k, hid]\n        return (self.wd[indices] @ (nn.silu(hg) * hu)[..., None])[..., 0]\n    def sorted_experts(self, x, indices):\n        y = self(x, indices); y2 = y.reshape(-1, y.shape[-1]); n = y2.shape[0]\n/;
s/            y = SwitchGLU\.__call__\(blk\.switch_mlp, mixed, ids\)                       # \[1, S, K, D\], rank order\n/            y = blk.switch_mlp(mixed, ids)                                           # [1, S, K, D], rank order\n/;
s/from mlx_lm\.models\.switch_layers import SwitchGLU\n//;
s/narrow path of the MoE wrapper\. Two stand-ins only: the mixer \(a per-row linear map; never-wait does not touch it\) and\nthe fused switch layer.s sorted_experts \(the stock expert outputs in a shuffled order with the inverse permutation\)\./narrow path of the MoE wrapper. Two stand-ins only, neither touched by never-wait: the mixer (a per-row linear map) and\nthe routed experts themselves (small gated MLPs; sorted_experts hands their outputs over in a shuffled order with the\ninverse permutation, as the fused switch layer does). float64 because 48 random layers amplify float32 rounding noise\nabout 5,000 x, which would blur "harness == reference"; NW_TEST_DTYPE=float32 NW_TEST_LAYERS=6 runs the small form./;
